	@Test
	public void testFrozenNativeCountKeepsBorrowedRootUsableAcrossQuadAndValueMapGrowth(@TempDir File root)
			throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setTripleDBSize(4096L * 10)
				.setValueDBSize(1024L * 1024);
		ValueStore values = new ValueStore(new File(root, "values"), config);
		CountDownLatch writerCommitAttempted = new CountDownLatch(1);
		AtomicBoolean observeWriterCommit = new AtomicBoolean();
		class CommitObservedTripleStore extends TripleStore {
			CommitObservedTripleStore() throws Exception {
				super(new File(root, "triples"), config, values);
			}

			@Override
			public void commit() throws java.io.IOException {
				if (observeWriterCommit.get()) {
					writerCommitAttempted.countDown();
				}
				super.commit();
			}
		}
		CommitObservedTripleStore smallStore = new CommitObservedTripleStore();
		ExecutorService executor = Executors.newSingleThreadExecutor();
		Future<?> writer = null;
		try {
			SimpleValueFactory valueFactory = SimpleValueFactory.getInstance();
			Resource subject = valueFactory.createIRI("urn:map-growth:subject");
			IRI predicate = valueFactory.createIRI("urn:map-growth:predicate");
			Value firstObject = valueFactory.createLiteral("initial-object-one-with-stored-value");
			Value secondObject = valueFactory.createLiteral("initial-object-two-with-stored-value");
			Statement first = valueFactory.createStatement(subject, predicate, firstObject);
			Statement second = valueFactory.createStatement(subject, predicate, secondObject);
			Value notInBatch = valueFactory.createLiteral("not-in-the-batch");
			long subjectId = values.storeValue(subject);
			long predicateId = values.storeValue(predicate);
			long firstObjectId = values.storeValue(firstObject);
			long secondObjectId = values.storeValue(secondObject);
			smallStore.startTransaction();
			smallStore.storeTriple(subjectId, predicateId, firstObjectId, 0, true);
			smallStore.storeTriple(subjectId, predicateId, secondObjectId, 0, true);
			smallStore.commit();
			values.commit();

			long initialTripleMapSize;
			try (Txn stats = smallStore.getTxnManager().createReadTxn()) {
				initialTripleMapSize = mapSize(stats.get());
			}
			long initialValueMapSize;
			try (Txn stats = values.getTxnManager().createReadTxn()) {
				initialValueMapSize = mapSize(stats.get());
			}
			long maxValue = Long.MAX_VALUE >>> 7;
			long growthSubjectId = ValueIds.createId(ValueIds.T_URI, maxValue);
			long growthPredicateId = ValueIds.createId(ValueIds.T_URI, maxValue - 1);
			long growthContextId = ValueIds.createId(ValueIds.T_URI, maxValue - 2);
			long firstGrowthObjectValue = maxValue - 3;
			long firstGrowthObjectId = ValueIds.createId(ValueIds.T_LITERAL, firstGrowthObjectValue);
			int firstGrowthKeyBytes = Varint.calcListLengthUnsigned(growthSubjectId, growthPredicateId,
					firstGrowthObjectId, growthContextId);
			int growthBatchSize = Math.toIntExact(Math.max(initialTripleMapSize, initialValueMapSize)
					/ firstGrowthKeyBytes + 1);
			long lastGrowthObjectId = ValueIds.createId(ValueIds.T_LITERAL,
					firstGrowthObjectValue - (growthBatchSize - 1L));
			int minimumGrowthKeyBytes = Varint.calcListLengthUnsigned(growthSubjectId, growthPredicateId,
					lastGrowthObjectId, growthContextId);
			assertEquals("The full-width synthetic IDs must keep one key width across the batch",
					firstGrowthKeyBytes, minimumGrowthKeyBytes);
			long minimumQuadBytes = (long) growthBatchSize * minimumGrowthKeyBytes;
			assertTrue("The staged tuple keys must exceed the measured triple map capacity",
					minimumQuadBytes > initialTripleMapSize);
			assertTrue("The staged tuple keys must exceed the measured value map capacity",
					minimumQuadBytes > initialValueMapSize);
			assertTrue("Each stored ASCII literal payload must be at least one tuple key",
					"map-growth-value-0-stored-lexical-payload-longer-than-inline".length() >= minimumGrowthKeyBytes);
			Txn borrowedRoot = smallStore.getTxnManager().createReadTxn();
			try {
				AtomicBoolean writerFinishedBatch = new AtomicBoolean();
				observeWriterCommit.set(true);

				try (StatementCountScope scope = new StatementCountScope(null, null, null, new Resource[0])) {
					StatementCountSource nativeSource = new LmdbStatementCountSource(smallStore, values, borrowedRoot,
							true, scope);
					StatementCountSource heldSource = StatementCountSources.fromStatements(
							new Statement[] { first, second }, scope);
					ValueStore.CountReadResource dictionary = values.prepareCountRead(scope);
					scope.prepareValue(notInBatch);
					assertTrue(
							"The native count scope must freeze before the writer attempts to publish its growth batch",
							scope.freeze());
					writer = executor.submit(() -> {
						smallStore.startTransaction();
						try {
							// High, typed IDs force full-width native keys; count scans never materialize these
							// dictionary IDs.
							for (int i = 0; i < growthBatchSize; i++) {
								long objectId = ValueIds.createId(ValueIds.T_LITERAL, firstGrowthObjectValue - i);
								smallStore.storeTriple(growthSubjectId, growthPredicateId, objectId, growthContextId,
										true);
							}
							smallStore.commit();
							writerFinishedBatch.set(true);
							values.startTransaction(true);
							try {
								for (int i = 0; i < growthBatchSize; i++) {
									values.storeValue(values.createLiteral(
											"map-growth-value-" + i + "-stored-lexical-payload-longer-than-inline"));
								}
								values.commit();
							} catch (Exception e) {
								values.rollback();
								throw e;
							}
						} catch (Exception e) {
							smallStore.rollback();
							throw e;
						}
						return null;
					});
					assertTrue("The writer must reach the blocked commit with its growth batch staged",
							writerCommitAttempted.await(10, TimeUnit.SECONDS));
					assertEquals("The captured count root must keep the original rows", 2,
							nativeSource.count(null, null, null, new Resource[0], null, scope));
					assertEquals("The held-key correction must use the same borrowed root", 2,
							nativeSource.count(null, null, null, new Resource[0],
									StatementCountSources.contains(heldSource), scope));
					assertEquals("The original object remains in the frozen root", 1,
							nativeSource.count(subject, predicate, secondObject, new Resource[0],
									StatementCountSources.contains(heldSource), scope));
					assertEquals("The writer batch stays invisible before publication", 0,
							nativeSource.count(subject, predicate, notInBatch,
									new Resource[0], StatementCountSources.contains(heldSource), scope));
					assertEquals("Quad map size cannot change while the count scope holds its guard",
							initialTripleMapSize,
							mapSize(borrowedRoot.get()));
					assertEquals("Value map size cannot change while the count scope holds its guard",
							initialValueMapSize,
							mapSize(dictionary.txn()));
				}

				writer.get(30, TimeUnit.SECONDS);
				assertTrue("The writer must finish after the frozen count releases its guards",
						writerFinishedBatch.get());
				long grownTripleMapSize;
				try (Txn stats = smallStore.getTxnManager().createReadTxn()) {
					grownTripleMapSize = mapSize(stats.get());
				}
				long grownValueMapSize;
				try (Txn stats = values.getTxnManager().createReadTxn()) {
					grownValueMapSize = mapSize(stats.get());
				}
				assertTrue("The staged quad batch must grow the real native triple map (initial="
						+ initialTripleMapSize + ", grown=" + grownTripleMapSize + ")",
						grownTripleMapSize > initialTripleMapSize);
				assertTrue("The writer's stored values must grow the real native value map (initial="
						+ initialValueMapSize + ", grown=" + grownValueMapSize + ")",
						grownValueMapSize > initialValueMapSize);

				try (StatementCountScope scope = new StatementCountScope(null, null, null, new Resource[0])) {
					StatementCountSource nativeSource = new LmdbStatementCountSource(smallStore, values, borrowedRoot,
							true, scope);
					assertTrue(scope.freeze());
					assertEquals("The supplied root must remain usable after growth and transaction renewal",
							growthBatchSize + 2,
							nativeSource.count(null, null, null, new Resource[0], null, scope));
				}
			} finally {
				borrowedRoot.close();
			}
		} finally {
			if (writer != null && !writer.isDone()) {
				writer.cancel(true);
			}
			executor.shutdownNow();
			try {
				smallStore.close();
			} finally {
				values.close();
			}
		}
	}

	private static long mapSize(long txn) {
		try (MemoryStack stack = MemoryStack.stackPush()) {
			MDBEnvInfo info = MDBEnvInfo.malloc(stack);
			assertEquals(MDB_SUCCESS, mdb_env_info(mdb_txn_env(txn), info));
			return info.me_mapsize();
		}
	}

	@Test
	public void testInferredStmts() throws Exception {
		tripleStore.startTransaction();
		tripleStore.storeTriple(1, 2, 3, 1, false);
		tripleStore.commit();

		try (Txn txn = tripleStore.getTxnManager().createReadTxn()) {
			assertEquals("Store should have 1 inferred statement", 1,
					count(tripleStore.getTriples(txn, 1, 2, 3, 1, false)));

			assertEquals("Store should have 0 explicit statements", 0,
					count(tripleStore.getTriples(txn, 1, 2, 3, 1, true)));

			tripleStore.startTransaction();
			tripleStore.storeTriple(1, 2, 3, 1, true);
			tripleStore.commit();

			assertEquals("Store should have 0 inferred statements", 0,
					count(tripleStore.getTriples(txn, 1, 2, 3, 1, false)));

			assertEquals("Store should have 1 explicit statements", 1,
					count(tripleStore.getTriples(txn, 1, 2, 3, 1, true)));
		}
	}

	@Test
	public void testExplicitPromotionRemovesSecondaryInferredRows() throws Exception {
		File secondaryIndexDir = new File(dataDir, "secondary-index-store");
		secondaryIndexDir.mkdirs();
		try (TripleStore secondaryIndexStore = new TripleStore(secondaryIndexDir, new LmdbStoreConfig("spoc,ospc,psoc"),
				null)) {
			secondaryIndexStore.startTransaction();
			secondaryIndexStore.storeTriple(11, 22, 33, 44, false);
			secondaryIndexStore.commit();

			secondaryIndexStore.startTransaction();
			secondaryIndexStore.storeTriple(11, 22, 33, 44, true);
			secondaryIndexStore.commit();

			try (Txn txn = secondaryIndexStore.getTxnManager().createReadTxn()) {
				assertEquals("PSOC inferred row should be removed", 0,
						count(secondaryIndexStore.getTriples(txn, -1, 22, -1, -1, false)));
				assertEquals("OSPC inferred row should be removed", 0,
						count(secondaryIndexStore.getTriples(txn, -1, -1, 33, -1, false)));
				assertEquals("PSOC explicit row should exist", 1,
						count(secondaryIndexStore.getTriples(txn, -1, 22, -1, -1, true)));
				assertEquals("OSPC explicit row should exist", 1,
						count(secondaryIndexStore.getTriples(txn, -1, -1, 33, -1, true)));
			}
		}
	}

	@Test
	public void testAlignedWriteFallbackRemovesSecondaryInferredRowsForPromotions() throws Exception {
		File fallbackDir = new File(dataDir, "aligned-fallback-store");
		fallbackDir.mkdirs();
		try (TripleStore fallbackStore = new TripleStore(fallbackDir, new LmdbStoreConfig("spoc,ospc,psoc"), null)) {
			long[] subj = { 11 };
			long[] pred = { 22 };
			long[] obj = { 33 };
			long[] context = { 44 };

			fallbackStore.startTransaction();
			fallbackStore.storeTriple(subj[0], pred[0], obj[0], context[0], false);
			fallbackStore.commit();

			fallbackStore.startTransaction();
			TripleIndex mainIndex = getIndexes(fallbackStore).getFirst();
			long writeTxn = getWriteTxn(fallbackStore);
			try (MemoryStack stack = MemoryStack.stackPush()) {
				MDBVal keyVal = MDBVal.malloc(stack);
				MDBVal dataVal = MDBVal.calloc(stack);
				ByteBuffer keyBuf = stack.malloc(TripleIndex.MAX_KEY_LENGTH);
				mainIndex.toKey(keyBuf, subj[0], pred[0], obj[0], context[0]);
				keyBuf.flip();
				keyVal.mv_data(keyBuf);
				LmdbUtil.E(mdb_put(writeTxn, mainIndex.getDB(true), keyVal, dataVal, MDB_NOOVERWRITE));
				assertEquals("Main inferred row should be removed before fallback replay", MDB_SUCCESS,
						mdb_del(writeTxn, mainIndex.getDB(false), keyVal, dataVal));
			}

			Method fallBackFromAlignedWrite = TripleStore.class.getDeclaredMethod("fallBackFromAlignedWrite",
					int[].class, int.class, long[].class, long[].class, long[].class, long[].class, boolean[].class,
					int.class, int.class, boolean.class, LongIntHashMap.class, IntConsumer.class);
			fallBackFromAlignedWrite.setAccessible(true);
			fallBackFromAlignedWrite.invoke(fallbackStore, new int[] { 0 }, 1, subj, pred, obj, context,
					new boolean[] { true }, 1, 1, true, new LongIntHashMap(), null);
			fallbackStore.commit();

			try (Txn txn = fallbackStore.getTxnManager().createReadTxn()) {
				assertEquals("PSOC inferred row should be removed after fallback replay", 0,
						count(fallbackStore.getTriples(txn, -1, pred[0], -1, -1, false)));
				assertEquals("OSPC inferred row should be removed after fallback replay", 0,
						count(fallbackStore.getTriples(txn, -1, -1, obj[0], -1, false)));
				assertEquals("PSOC explicit row should exist after fallback replay", 1,
						count(fallbackStore.getTriples(txn, -1, pred[0], -1, -1, true)));
				assertEquals("OSPC explicit row should exist after fallback replay", 1,
						count(fallbackStore.getTriples(txn, -1, -1, obj[0], -1, true)));
			}
		}
	}

	@Test
	public void testLeadingFieldSortPreservesPriorOrderWithinGroups() throws Exception {
		Method method = TripleStore.class.getDeclaredMethod("sortStatementIndicesByLeadingField", int[].class,
				int.class, TripleIndex.class, long[].class, long[].class, long[].class, long[].class);
		method.setAccessible(true);
		Field indexesField = TripleStore.class.getDeclaredField("indexes");
		indexesField.setAccessible(true);

		@SuppressWarnings("unchecked")
		List<TripleIndex> indexes = (List<TripleIndex>) indexesField.get(tripleStore);

		int[] statementIndices = { 0, 1, 2, 3 };
		long[] subj = { 1, 2, 3, 4 };
		long[] pred = { 5, 5, 5, 5 };
		long[] obj = { 10, 20, 30, 40 };
		long[] context = { 100, 200, 300, 400 };

		method.invoke(tripleStore, statementIndices, statementIndices.length, indexes.get(1), subj, pred, obj, context);

		assertEquals("Leading-field sort should preserve prior order for identical leading values",
				Arrays.toString(new int[] { 0, 1, 2, 3 }), Arrays.toString(statementIndices));
	}

	@Test
	public void testLeadingFieldSortIgnoresFullKeySortProperty() throws Exception {
		String previousAlignedWriteStrategy = System.getProperty("rdf4j.lmdb.alignedWriteStrategy");
		System.setProperty("rdf4j.lmdb.alignedWriteStrategy", "FULL_KEY_SORT");

		File ignoredPropertyDir = new File(dataDir, "ignored-full-key-sort-property");
		ignoredPropertyDir.mkdirs();

		try (TripleStore ignoredPropertyStore = new TripleStore(ignoredPropertyDir, new LmdbStoreConfig("spoc,posc"),
				null)) {
			Method method = TripleStore.class.getDeclaredMethod("sortStatementIndicesByLeadingField", int[].class,
					int.class, TripleIndex.class, long[].class, long[].class, long[].class, long[].class);
			method.setAccessible(true);
			Field indexesField = TripleStore.class.getDeclaredField("indexes");
			indexesField.setAccessible(true);

			@SuppressWarnings("unchecked")
			List<TripleIndex> indexes = (List<TripleIndex>) indexesField
					.get(ignoredPropertyStore);

			int[] statementIndices = { 0, 1, 2, 3 };
			long[] subj = { 101, 102, 103, 104 };
			long[] pred = { 7, 7, 7, 7 };
			long[] obj = { 20, 10, 40, 30 };
			long[] context = { 0, 0, 0, 0 };

			method.invoke(ignoredPropertyStore, statementIndices, statementIndices.length, indexes.get(1), subj, pred,
					obj,
					context);

			assertEquals("Leading-field sort should ignore legacy full-key strategy configuration",
					Arrays.toString(new int[] { 0, 1, 2, 3 }), Arrays.toString(statementIndices));
		} finally {
			if (previousAlignedWriteStrategy == null) {
				System.clearProperty("rdf4j.lmdb.alignedWriteStrategy");
			} else {
				System.setProperty("rdf4j.lmdb.alignedWriteStrategy", previousAlignedWriteStrategy);
			}
		}
	}

